package com.fireplatform;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fireplatform.shared.*;
import com.fireplatform.simembedded.*;
import java.math.*;
import java.sql.ResultSet;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.fireplatform.simembedded.SimEmbeddedModels.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class SimEmbeddedProjectionTest {
    static final String DEVICE="legacy-device",TENANT="tenant-a",CHANGE="123e4567-e89b-12d3-a456-426614174000",TIME="2026-01-02T03:04:05.123456Z";
    final ObjectMapper json=new ObjectMapper().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).enable(DeserializationFeature.USE_BIG_INTEGER_FOR_INTS).enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
    Profile profile(long revision){return new Profile(DEVICE,TENANT,null,"","EMBEDDED","UNKNOWN","UNKNOWN","UNKNOWN","UNKNOWN",null,null,"","MANUAL",revision,TIME);}
    ObjectNode node(){return json.valueToTree(profile(1));}
    void bad(org.assertj.core.api.ThrowableAssert.ThrowingCallable work){assertThatThrownBy(work).isInstanceOfSatisfying(ApiError.class,e->{assertThat(e.status).isEqualTo(503);assertThat(e.code).isEqualTo("SIM_EMBEDDED_READ_UNCONFIRMED");assertThat(e.getMessage()).doesNotContain("SECRET");});}
    ResultSet row(Profile profile)throws Exception{var rs=mock(ResultSet.class);Map<String,String> fields=new HashMap<>();fields.put("device_id",profile.deviceId());fields.put("tenant_id",profile.tenantId());fields.put("iccid",profile.iccid());fields.put("carrier_name",profile.carrierName());fields.put("installation_form",profile.installationForm());fields.put("replaceability",profile.replaceability());fields.put("management_party",profile.managementParty());fields.put("fee_responsibility",profile.feeResponsibility());fields.put("reported_operator_status",profile.reportedOperatorStatus());fields.put("source_note",profile.sourceNote());fields.put("information_source",profile.informationSource());fields.put("change_id",CHANGE);fields.put("operation","RECORD");fields.put("reason"," original reason ");when(rs.getString(anyString())).thenAnswer(call->fields.get(call.getArgument(0,String.class)));when(rs.getObject("revision")).thenReturn(profile.revision());when(rs.getObject("expires_on",LocalDate.class)).thenReturn(profile.expiresOn()==null?null:LocalDate.parse(profile.expiresOn()));when(rs.getObject("evidence_at",OffsetDateTime.class)).thenReturn(profile.evidenceAt()==null?null:OffsetDateTime.parse(profile.evidenceAt()));when(rs.getObject("recorded_at",OffsetDateTime.class)).thenReturn(profile.recordedAt()==null?null:OffsetDateTime.parse(profile.recordedAt()));return rs;}
    @Test void currentHistoryAndPagesHaveExactShapesWithoutChangedOrActor(){assertThat(node().size()).isEqualTo(15);var change=new Change(CHANGE,DEVICE,TENANT,1,"RECORD",profile(1),"",TIME);JsonNode history=json.valueToTree(change);assertThat(history.size()).isEqualTo(8);assertThat(history.get("profile").size()).isEqualTo(15);assertThat(history.get("profile").has("change_id")).isFalse();assertThat(history.toString()).doesNotContain("actor","username","device_name","changed");assertThat(json.valueToTree(new HistoryPage(List.of(change),1,1,20,1)).size()).isEqualTo(5);}
    @Test void virtualZeroIsOnlyTheExactUnregisteredManualDefault(){var value=SimEmbeddedProjection.empty(TENANT,DEVICE);assertThat(value.revision()).isZero();assertThat(value.recordedAt()).isNull();assertThat(value.iccid()).isNull();assertThat(value.installationForm()).isEqualTo("EMBEDDED");ObjectNode virtual=json.valueToTree(value);for(String key:List.of("iccid","carrier_name","source_note","expires_on","evidence_at","recorded_at","replaceability","management_party","fee_responsibility","reported_operator_status")){var n=virtual.deepCopy();n.put(key,key.equals("recorded_at")||key.equals("evidence_at")?TIME:key.equals("expires_on")?"2026-01-01":key.equals("carrier_name")||key.equals("source_note")||key.equals("iccid")?"recorded":"OTHER");bad(()->SimEmbeddedProjection.stored(n));}}
    @Test void nullTimestampRequiresZeroAndPersistedRowsNeverUseVirtualZero()throws Exception{bad(()->SimEmbeddedProjection.valid(new Profile(DEVICE,TENANT,null,"","EMBEDDED","UNKNOWN","UNKNOWN","UNKNOWN","UNKNOWN",null,null,"","MANUAL",1,null),TENANT,DEVICE));bad(()->SimEmbeddedProjection.profile(row(SimEmbeddedProjection.empty(TENANT,DEVICE)),TENANT,DEVICE));}
    @Test void completePositiveAndVirtualProfilesRoundTripStrictly()throws Exception{for(Profile profile:List.of(profile(1),profile(2),SimEmbeddedProjection.empty(TENANT,DEVICE)))assertThat(json.readValue(json.writeValueAsBytes(profile),Profile.class)).isEqualTo(profile);}
    @Test void everyStoredKeyIsRequiredAndNoExtraActorOrCardFieldIsAllowed(){for(String key:SimEmbeddedProjection.PROFILE_COLUMNS.split(",")){var n=node();n.remove(key);bad(()->SimEmbeddedProjection.stored(n));}for(String key:List.of("actor_user_id","change_id","card_id","changed","SECRET")){var n=node();n.put(key,"SECRET");bad(()->SimEmbeddedProjection.stored(n));}}
    @Test void storedScalarsAndNullableFieldsNeverCoerce(){for(String key:SimEmbeddedProjection.PROFILE_COLUMNS.split(","))if(!key.equals("revision")){var n=node();n.put(key,1);bad(()->SimEmbeddedProjection.stored(n));}for(String key:List.of("device_id","tenant_id","carrier_name","installation_form","replaceability","management_party","fee_responsibility","reported_operator_status","source_note","information_source")){var n=node();n.putNull(key);bad(()->SimEmbeddedProjection.stored(n));}}
    @Test void rawCachedNegativeZeroExponentFractionStringAndUnsafeRevisionFail()throws Exception{String valid=json.writeValueAsString(SimEmbeddedProjection.empty(TENANT,DEVICE));for(String raw:List.of("-0","0.0","0e0","\"0\"","9007199254740992","-1"))assertThatThrownBy(()->json.readValue(valid.replace("\"revision\":0","\"revision\":"+raw),Profile.class)).isInstanceOf(Exception.class);}
    @Test void cachedDuplicateTrailingRootNullAndMalformedNeverBecomeCacheMiss()throws Exception{String valid=json.writeValueAsString(profile(1));List<String> badJson=List.of("null","[]","{",valid+" {}",valid.replace("\"revision\":1","\"revision\":1,\"revision\":1"),valid.substring(0,valid.length()-1)+",\"source_note\":\"duplicate\"}");for(String raw:badJson)assertThatThrownBy(()->json.readValue(raw,Profile.class)).isInstanceOf(Exception.class);}
    @Test void wrongScopeBadDeviceIdentityAndLegacyRemovableShapeFail(){bad(()->SimEmbeddedProjection.valid(profile(1),"tenant-b",DEVICE));bad(()->SimEmbeddedProjection.valid(profile(1),TENANT,"other"));for(String key:List.of("device_id","tenant_id")){var n=node();n.put(key," SECRET ");bad(()->SimEmbeddedProjection.valid(SimEmbeddedProjection.stored(n),TENANT,DEVICE));}var removable=node();removable.put("installation_form","REMOVABLE");bad(()->SimEmbeddedProjection.stored(removable));}
    @Test void knownIccidCanChangeOrBecomeNullButStoredTextMustBeCanonical(){var n=node();n.put("iccid","000Known");assertThat(SimEmbeddedProjection.stored(n).iccid()).isEqualTo("000Known");n.putNull("iccid");assertThat(SimEmbeddedProjection.stored(n).iccid()).isNull();for(String key:List.of("iccid","carrier_name","source_note")){var bad=node();bad.put(key," unnormalized ");bad(()->SimEmbeddedProjection.stored(bad));}}
    @Test void datesAndTimestampsKeepTrueUtcMicrosecondsAndCanonicalNullableValues(){for(String time:List.of("2026-01-02T03:04:05Z","2026-01-02T03:04:05.1Z","2026-01-02T03:04:05.123456+00:00","0000-01-01T00:00:00.000000Z","2026-01-02T24:00:00.000000Z")){var n=node();n.put("recorded_at",time);bad(()->SimEmbeddedProjection.stored(n));}var n=node();n.put("evidence_at","2026-01-02T03:04:05.1Z");bad(()->SimEmbeddedProjection.stored(n));n.put("evidence_at",TIME);n.put("expires_on","0001-01-01");assertThat(SimEmbeddedProjection.stored(n).evidenceAt()).isEqualTo(TIME);bad(()->SimEmbeddedProjection.instant(OffsetDateTime.parse("2026-01-02T03:04:05.123456789Z")));bad(()->SimEmbeddedProjection.instant(OffsetDateTime.of(9999,12,31,23,59,59,0,ZoneOffset.ofHours(-1))));}
    @Test void jdbcNumbersAreExactNotTruncatedOrNullDefaulted(){for(Object raw:Arrays.asList(null,-1L,SimEmbeddedInputs.MAX_SAFE+1,new BigDecimal("0.01"),0.0,"1",BigInteger.valueOf(Long.MAX_VALUE).add(BigInteger.ONE)))bad(()->SimEmbeddedProjection.number(raw));assertThat(SimEmbeddedProjection.number(BigInteger.valueOf(SimEmbeddedInputs.MAX_SAFE))).isEqualTo(SimEmbeddedInputs.MAX_SAFE);}
    @Test void sourceHistoryChecksOperationIdentityLastSnapshotAndMutableEarlierIccid()throws Exception{var current=profile(2);var old=row(profile(1));assertThat(SimEmbeddedProjection.change(old,current).revision()).isEqualTo(1);var bad=row(profile(2));when(bad.getString("iccid")).thenReturn("different");bad(()->SimEmbeddedProjection.change(bad,current));var operation=row(profile(1));when(operation.getString("operation")).thenReturn("CREATE");bad(()->SimEmbeddedProjection.change(operation,current));var id=row(profile(1));when(id.getString("change_id")).thenReturn("NOT_UUID");bad(()->SimEmbeddedProjection.change(id,current));}
    @Test void badCentralDefaultIs503EvenForExplicitSizeWithoutAnyJdbcQuery(){for(long value:new long[]{0,4,101,Long.MAX_VALUE})for(Integer requested:Arrays.asList(null,1)){var jdbc=mock(JdbcTemplate.class);var sizes=mock(PageSizePolicy.class);when(sizes.defaultPageSize()).thenReturn(value);var queries=new SimEmbeddedQueries(jdbc, sizes, mock(TransactionRequirements.class), new com.fireplatform.identity.DeviceScopes(jdbc));bad(()->queries.history(null,TENANT,DEVICE,1,requested));assertThat(mockingDetails(jdbc).getInvocations()).isEmpty();}}
    @Test void publicSqlColumnsNeverSelectActorNamesOrWildcards(){assertThat(SimEmbeddedProjection.PROFILE_COLUMNS.split(",")).hasSize(15);assertThat(SimEmbeddedProjection.CHANGE_COLUMNS).doesNotContain("actor","username","*","password");}
}
